import { useEffect, useRef, useState } from "react";

export function LikeButton() {
  const [likes, setLikes] = useState(0);
  const noteRef = useRef<HTMLInputElement>(null);
  const firstNode = useRef<HTMLInputElement | null>(null);

  console.log("render", likes); // every click: React called LikeButton again

  useEffect(() => {
    firstNode.current ??= noteRef.current;
    // Runs after every commit and always logs true: the <input> is never recreated
    console.log("same <input> node:", noteRef.current === firstNode.current);
  });

  return (
    <div>
      <button onClick={() => setLikes(likes + 1)}>Like ({likes})</button>
      <input ref={noteRef} placeholder="Add a note" />
    </div>
  );
}

