import { useState } from "react";

type SearchBoxProps = { query: string; onQueryChange: (query: string) => void };

// Declared once at the top level: the same component type on every render
function SearchBox({ query, onQueryChange }: SearchBoxProps) {
  return <input value={query} onChange={(e) => onQueryChange(e.target.value)} />;
}

export function SearchPage({ items }: { items: string[] }) {
  const [query, setQuery] = useState("");
  const visible = items.filter((item) => item.includes(query));
  return (
    <>
      <SearchBox query={query} onQueryChange={setQuery} />
      <ul>{visible.map((item) => <li key={item}>{item}</li>)}</ul>
    </>
  );
}
